/**
 * 365 questions quotidiennes Link Academy (formation commerciale / media).
 * Reformulations des quiz, de l'examen et des contenus du site — pas de copier-coller identique.
 */

/**
 * @typedef {{ category: string, question: string, options: string[], correctIndex: number, explanation: string }} DailyQuestion
 */

/**
 * @param {string} category
 * @param {string} question
 * @param {string[]} options
 * @param {number} correctIndex
 * @param {string} explanation
 * @returns {DailyQuestion}
 */
function q(category, question, options, correctIndex, explanation) {
  return { category, question, options, correctIndex, explanation }
}

const CIBLAGE = 'Ciblage publicitaire'
const FORMATS = 'Formats visuels et Studio'
const PLATEFORMES = 'Plateformes, placements et formats pub'
