const SCORE = 'Score qualité et enchères'
const METHODO = 'Méthodologie Link et rôles CM / TM'
const LEXIQUE = 'Lexique et définitions KPI'
const BILANS = 'Bilans, rapports et lecture de performance'
const OUTILS = 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)'
